  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C01","C02","C06","C10","C11","C12","C15","C17","C20","C22","C23","C26","C34","C49","C50","C51","C53","C54","C57"],
  "claims": [
    {
      "claim": "Esaxerenone, the closest structural context sharing the methyl-amide-aryl and CF3/OCF3-bearing biaryl motif, had absolute oral bioavailability of 89.0% fasting and 90.8% postprandial in healthy subjects; an L4 Caco-2 record for esaxerenone shows high basal-to-apical permeability (43.5 ×10^-6 cm/s), consistent with high permeability but not a direct F measurement.",
      "card_ids": ["C01","C02","C10","C11","C12","C20","C26","C54"]
    },
    {
      "claim": "Nilotinib, a lipophilic CF3-containing amide with precipitation-limited absorption, had absolute oral bioavailability of about 31% under fasted conditions, still above the 20% threshold.",
      "card_ids": ["C06","C22","C34"]
    },
    {
      "claim": "Elinzanetant, a lipophilic CF3-containing amide with a morpholine-type amine, had oral bioavailability of 36.7% and is described as orally bioavailable.",
      "card_ids": ["C15","C17","C23"]
    },
    {
      "claim": "L4 permeability records for OCF3-containing amides (HSGN-238, compound 4) and a netupitant-like CF3 amide show high Caco-2 permeability (e.g., 82.3, 22.6, >20 ×10^-6 cm/s), supporting adequate intestinal absorption for the lipophilic amide/OCF3 chemotype.",
      "card_ids": ["C49","C51","C53","C50","C57"]
    },
    {
      "claim": "Vismodegib is classified as high permeability but poor solubility (BCS II), and nilotinib's low F was attributed to precipitation; solubility remains a risk for the query but does not affirm F<20%.",
      "card_ids": ["C52","C58","C34"]
    },
    {
      "claim": "High efflux ratios in M08/M09 records are not query-specific and do not establish low F for the query.",
      "card_ids": ["C47","C55"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C47","C48","C49","C50","C51","C52","C53","C54","C55","C56","C57","C58"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No query-specific solubility or permeability measurement is available; L4 records are for reference molecules, not the query.",
    "No query-specific first-pass or systemic clearance data; the low prior is physicochemical only.",
    "Condition matching is imperfect: query has no reported external condition, while many contexts are fasted/fed/cirrhosis-specific.",
    "The query's 2,6-dimethylmorpholine-pyridine and OCF3 combination is not exactly covered by any card; closest analogs differ in polar substituents and formulation.",
    "Efflux (P-gp/BCRP) was not measured for the query; high efflux ratios in M08/M09 are not directly transferable."
  ],
  "decision_summary": "Prediction remains high: all transferable numeric gold records for structurally relevant amide/heteroaryl contexts are >=31%, with closest analogs esaxerenone (89-91%) and nilotinib (31%) supporting F>=20%; L4 permeability records for OCF3-containing amides and esaxerenone support adequate intestinal absorption, while solubility/efflux concerns are not affirmative evidence of F<20%. Confidence remains moderate because no direct query measurement is available."
}

